        if isinstance(circuit, bool):
            return circuit
        op, left, right = circuit
        if op == 'AND':
            return evaluate_circuit(left) and evaluate_circuit(right)
        elif op == 'OR':
            return evaluate_circuit(left) or evaluate_circuit(right)

